fn render_export_specifier(node: &ExportSpecifierTransport, w: &mut dyn ::sittir_core::render::RenderSink) -> ::sittir_core::render::RenderResult {
    let alias = View::new(&node.alias, "{}");
    let export_kind = View::new(&node.export_kind, "{}");
    let name = &node.name;
    w.edge(::sittir_core::types::KindId(187), ::sittir_core::options::Side::Before, node.edges.and_then(|e| e.before));
    export_kind.render(w)?;
    name.render(w)?;
    if alias.is_present() {
        w.site_at(options::SITE_EXPORT_SPECIFIER_AS_KEYWORD_BEFORE);
        w.text("as")?;
        w.site_at(options::SITE_EXPORT_SPECIFIER_AS_KEYWORD_AFTER);
        alias.render(w)?;
    }
    w.edge(::sittir_core::types::KindId(187), ::sittir_core::options::Side::After, node.edges.and_then(|e| e.after));
    Ok(())
}

