    w.site_at(options::SITE_INDEX_SIGNATURE_COLON_RBRACK_BEFORE);
    w.text("]")?;
    w.adjacent();
    w.site_at(options::SITE_INDEX_SIGNATURE_COLON_RBRACK_AFTER);
